class MedianFinder {
  private all: number[] = [];

  addNum(num: number): void {
    this.all.push(num);
  }

  findMedian(): number {
    const s = this.all.slice().sort((a, b) => a - b), n = s.length;
    return n % 2 ? s[n >> 1] : (s[n / 2 - 1] + s[n / 2]) / 2;
  }
}

