  private s: number[] = [];

  addNum(num: number): void {
    let lo = 0, hi = this.s.length; // first index with a value > num
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (this.s[mid] <= num) lo = mid + 1;
      else hi = mid;
    }
    this.s.splice(lo, 0, num);
  }

  findMedian(): number {
    const s = this.s, n = s.length;
    return n % 2 ? s[n >> 1] : (s[n / 2 - 1] + s[n / 2]) / 2;
  }
}

