class Heap {
  private a: number[] = [];
  constructor(private before: (x: number, y: number) => boolean) {} // true if x belongs above y
  get size(): number { return this.a.length; }
  peek(): number { return this.a[0]; }

  push(x: number): void {
    const a = this.a;
    a.push(x);
    let i = a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (!this.before(a[i], a[p])) break;
      [a[p], a[i]] = [a[i], a[p]];
      i = p;
    }
  }

  pop(): number {
    const a = this.a, top = a[0], last = a.pop()!;
    if (a.length) {
      a[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < a.length && this.before(a[l], a[m])) m = l;
        if (r < a.length && this.before(a[r], a[m])) m = r;
        if (m === i) break;
        [a[m], a[i]] = [a[i], a[m]];
        i = m;
      }
    }
    return top;
  }
}

class MedianFinder {
  private low = new Heap((x, y) => x > y);  // max-heap: lower half
  private high = new Heap((x, y) => x < y); // min-heap: upper half

  addNum(num: number): void {
    this.low.push(num);
    this.high.push(this.low.pop()); // the largest of the lower side crosses over
    if (this.high.size > this.low.size) this.low.push(this.high.pop());
  }

  findMedian(): number {
    if (this.low.size > this.high.size) return this.low.peek();
    return (this.low.peek() + this.high.peek()) / 2;
  }
}

